// Package hms describes HMS alerts and print error codes using the texts
// Bambu Lab publishes for Bambu Studio. The tables are generated by
// ./gen and embedded in the binary, so no internet access is needed.
package hms

import (
	"compress/gzip"
	"embed"
	"encoding/json"
	"log/slog"
	"net/url"
	"strings"
	"sync"
)

//go:embed data/*.json.gz
var data embed.FS

// Kinds of codes.
const (
	KindHMS   = "hms"   // 16 hex digits from the "hms" list of a report
	KindError = "error" // 8 hex digits from print_error
)

// table maps a code to texts by serial prefix; "" holds the default text.
type table map[string]map[string]string

type file struct {
	Version string `json:"version"`
	HMS     table  `json:"hms"`
	Errors  table  `json:"errors"`
}

var (
	mu    sync.Mutex
	files = map[string]*file{}
)

func load(lang string) *file {
	mu.Lock()
	defer mu.Unlock()
	if f, ok := files[lang]; ok {
		return f
	}
	var f *file
	if r, err := data.Open("data/hms_" + lang + ".json.gz"); err == nil {
		defer r.Close()
		if gz, err := gzip.NewReader(r); err == nil {
			f = &file{}
			if err := json.NewDecoder(gz).Decode(f); err != nil {
				slog.Error("invalid HMS table", "lang", lang, "err", err)
				f = nil
			}
		}
	}
	files[lang] = f
	return f
}

// Text returns the description of a code in lang, falling back to English,
// or "" when it is unknown. The printer serial selects model-specific texts.
func Text(lang, serial, kind, code string) string {
	key := normalize(code)
	for _, l := range []string{lang, "en"} {
		f := load(l)
		if f == nil {
			continue
		}
		t := f.HMS
		if kind == KindError {
			t = f.Errors
		}
		if m, ok := t[key]; ok {
			if s, ok := m[prefix(serial)]; ok {
				return s
			}
			return m[""]
		}
	}
	return ""
}

// HelpURL returns the Bambu Lab link that Bambu Studio opens for a code; it
// redirects to the wiki page of the code or to the HMS overview.
func HelpURL(lang, serial, kind, code string) string {
	s := "device_hms"
	if kind == KindError {
		s = "device_error"
	}
	q := url.Values{"e": {normalize(code)}, "s": {s}, "lang": {lang}}
	if p := prefix(serial); p != "" {
		q.Set("d", p)
	}
	return "https://e.bambulab.com/index.php?" + q.Encode()
}

// Severity returns the level encoded in the code part of an HMS entry.
func Severity(code uint32) string {
	switch code >> 16 {
	case 1:
		return "fatal"
	case 2:
		return "serious"
	case 3:
		return "common"
	case 4:
		return "info"
	}
	return ""
}

func normalize(code string) string {
	return strings.ToUpper(strings.ReplaceAll(code, "_", ""))
}

// prefix identifies the printer type, as Bambu Studio does.
func prefix(serial string) string {
	if len(serial) < 3 {
		return ""
	}
	return strings.ToUpper(serial[:3])
}
